-- ---------- SPRITES em pixel art, guardados como texto ----------
-- Cada letra é uma cor da paleta; '.' é transparente.
-- Na xilogravura cada cor vira: tinta, papel (entalhado), destaque (vermelho)
-- ou contraste (o oposto dos vizinhos: um olho preto num rosto claro, um olho
-- claro num corpo preto).
CREATE TABLE paleta (ch VARCHAR, cor VARCHAR, tinta VARCHAR);
